class Dompet(var saldo: Int, var diblokir: Boolean = false) {
    fun transfer(jumlah: Int) {
        require(jumlah >= 10_000) { "Minimal transfer Rp10.000" }
        check(!diblokir) { "Dompet sedang diblokir" }
        if (jumlah > saldo) throw IllegalStateException("Saldo tidak cukup")
        saldo -= jumlah
    }
}

fun main() {
    val d = Dompet(50_000)
    try { d.transfer(5_000) } catch (e: IllegalArgumentException) { println("Ditolak: ${e.message}") }
