class Antrean<T> {
    val isi = mutableListOf<T>()
    fun masuk(x: T) { isi.add(x) }
    fun panggil(): T? = if (isi.isEmpty()) null else isi.removeAt(0)
    val panjang: Int get() = isi.size
}

